ALTER TABLE "assets" ADD CONSTRAINT "assets_failure_code_value_check" CHECK ("assets"."failure_code" IS NULL OR "assets"."failure_code" IN ('UPLOAD_EXPIRED', 'MEDIA_TOO_LARGE', 'MEDIA_LIMIT_EXCEEDED', 'MEDIA_TYPE_MISMATCH', 'UNSUPPORTED_MEDIA', 'INVALID_MEDIA', 'UNSAFE_MEDIA_URL', 'MEDIA_SOURCE_UNAVAILABLE', 'PROCESSING_UNAVAILABLE'));